import redis.clients.jedis.HostAndPort;
import redis.clients.jedis.JedisCluster;
import java.util.HashSet;
import java.util.Set;

public class ResilientRedisClientFactory {
    public static JedisCluster createClusterClient() {
        Set<HostAndPort> clusterNodes = new HashSet<>();
        clusterNodes.add(new HostAndPort("redis-node-1.internal", 6379));
        clusterNodes.add(new HostAndPort("redis-node-2.internal", 6379));
        clusterNodes.add(new HostAndPort("redis-node-3.internal", 6379));

        // JedisCluster automatically handles node failure, MOVED/ASK redirections,
        // and topology refreshing when a master node dies and a replica is promoted.
        return new JedisCluster(clusterNodes);
    }
}
